#!/usr/bin/env bash
# Generated by scripts/build-bootstrap.py; no credentials are embedded.
set -euo pipefail
ROLE=main
if [[ " ${*} " == *" --help "* || " ${*} " == *" -h "* ]]; then
  cat <<'HELP'
DAO Linux 一键安装：Debian 12/13、Ubuntu 22.04/24.04，amd64/arm64，systemd。
主站：sudo bash install-main.sh --version v0.4.0-rc.12
IP HTTPS：新主站默认自动识别公网 IP 并申请/续期证书，保持 TCP 80/443 开放。
访问保护：新主站默认启用 HTTP Basic Auth，凭据见 /etc/dao/basic-auth.json；通过后再用管理员密码登录。
手动指定：--public-ip IP；重新识别：--public-ip auto；已有代理：--listen 127.0.0.1。
私有仓库：--github-token-file /root/readonly-token，或运行时隐藏输入。
Worker：复制主站“远程 Worker → 安装与接入”生成的安装命令，无需 GitHub Token。
已有配置：sudo bash install-worker.sh --config /etc/dao-worker/config.json
只修主机名：sudo bash install-main.sh --repair-hostname（不安装、不重启 DAO）。
保留离线包/指定下载：--bundle-dir DIR，或 --bundle-url HTTPS_URL --sha256 HASH。
重装保留数据；升级前暂停/完成任务并停止服务。--tools standard|minimal。
HELP
  exit 0
fi
[[ $EUID -eq 0 ]] || { echo '请以 root 或 sudo bash 运行。' >&2; exit 1; }
[[ $(uname -s) == Linux ]] || { echo '仅支持 Linux。' >&2; exit 1; }
source /etc/os-release
case "${ID}:${VERSION_ID}" in
  debian:12|debian:13|ubuntu:22.04|ubuntu:24.04) ;;
  *) echo '支持 Debian 12/13、Ubuntu 22.04/24.04。' >&2; exit 1 ;;
esac
if ! command -v python3 >/dev/null || [[ ! -f /etc/ssl/certs/ca-certificates.crt ]]; then
  export DEBIAN_FRONTEND=noninteractive
  apt-get update
  apt-get install -y --no-install-recommends python3 ca-certificates
fi
SCRIPT_DIR=/nonexistent/dao-installer
if [[ -n "${BASH_SOURCE[0]:-}" && -f "${BASH_SOURCE[0]}" ]]; then
  SCRIPT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
fi
python3 - "$ROLE" "$SCRIPT_DIR" "$@" <<'PY'
"""Standalone, generated public installer. Contains no deployment credentials."""
import argparse
import datetime
import getpass
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import platform
import re
import secrets
import shutil
import socket
import stat
import subprocess
import sys
import tempfile
import time
import urllib.error
import urllib.parse
import urllib.request
import zipfile

REPO = os.environ.get('DAO_RELEASE_REPO', 'nidieshiwo-dao/DAO').strip()
TAG = re.compile(r'^v(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-[0-9A-Za-z]+([.-][0-9A-Za-z]+)*)?$')
CDN = {'release-assets.githubusercontent.com', 'objects.githubusercontent.com'}
SECRETS = []
LOG = None
LOG_BYTES = 0
PENDING = Path('/etc/dao-worker/install.pending.json')

def log(message):
    global LOG_BYTES
    text = str(message)
    for secret in SECRETS:
        if secret: text = text.replace(secret, '[REDACTED]')
    text = re.sub(r'gh[pousr]_[A-Za-z0-9_]+|github_pat_[A-Za-z0-9_]+', '[REDACTED]', text)
    text = re.sub(r'https://[^\s]+\?[^\s]+', '[download URL]', text)
    text = text[:8192]
    print(text, flush=True)
    if LOG and LOG_BYTES < 8 * 1024**2:
        line = datetime.datetime.now(datetime.timezone.utc).isoformat() + ' ' + text + '\n'
        LOG.write(line); LOG.flush(); LOG_BYTES += len(line.encode())

def atomic_json(path, value):
    path = Path(path)
    if path.is_symlink(): raise ValueError('拒绝写入符号链接配置')
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    fd, tmp = tempfile.mkstemp(prefix='.dao-', dir=path.parent)
    try:
        with os.fdopen(fd, 'w') as f:
            json.dump(value, f); f.flush(); os.fsync(f.fileno())
        os.chmod(tmp, 0o600); os.replace(tmp, path)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)

def valid_https(url, hosts=None):
    u = urllib.parse.urlsplit(url)
    return u.scheme == 'https' and bool(u.hostname) and not u.username and not u.password and (hosts is None or (u.hostname in hosts and u.port is None))

class Redirect(urllib.request.HTTPRedirectHandler):
    def __init__(self, hosts=None): self.hosts = hosts
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        if not valid_https(newurl, self.hosts): raise ValueError('拒绝不安全下载跳转')
        # Credentials are deliberately unredirected; never forward them to a CDN.
        return super().redirect_request(req, fp, code, msg, headers, newurl)

class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, *args, **kwargs): return None

def fetch_json(url, token='', payload=None):
    if not valid_https(url): raise ValueError('接口必须使用 HTTPS')
    headers = {'Accept': 'application/vnd.github+json', 'User-Agent': 'DAO-installer', 'Content-Type': 'application/json'}
    req = urllib.request.Request(url, data=json.dumps(payload).encode() if payload is not None else None, headers=headers)
    if token: req.add_unredirected_header('Authorization', 'Bearer ' + token)
    for attempt in range(3):
        try:
            with urllib.request.build_opener(NoRedirect()).open(req, timeout=45) as r:
                raw = r.read(1024**2 + 1)
                if len(raw) > 1024**2: raise ValueError('接口响应过大')
                return json.loads(raw)
        except urllib.error.HTTPError as e:
            if e.code >= 500 and attempt < 2: time.sleep(attempt + 1); continue
            raise ValueError(f'接口 HTTP {e.code}：检查下载权限、版本或节点安装凭证；预览版须指定 --version') from None
        except (urllib.error.URLError, TimeoutError):
            if attempt < 2: time.sleep(attempt + 1); continue
            raise ValueError('接口连接失败；可重跑同一安装命令') from None

def asset_url(repo, asset, token):
    if not isinstance(asset.get('id'), int) or asset['id'] <= 0: raise ValueError('无效资产编号')
    req = urllib.request.Request(f'https://api.github.com/repos/{repo}/releases/assets/{asset["id"]}', headers={'Accept':'application/octet-stream','User-Agent':'DAO-installer'})
    if token: req.add_unredirected_header('Authorization', 'Bearer ' + token)
    try:
        with urllib.request.build_opener(NoRedirect()).open(req, timeout=45):
            raise ValueError('GitHub 未返回直接下载地址')
    except urllib.error.HTTPError as e:
        if e.code not in (302, 307): raise ValueError(f'获取下载授权失败 (HTTP {e.code})') from None
        url = e.headers.get('Location', '')
        if not valid_https(url, CDN): raise ValueError('无效 GitHub 下载地址')
        return url

def github_manifest(repo, version, arch, token):
    if not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9-]*/[A-Za-z0-9_.-]+', repo): raise ValueError('仓库必须是 owner/repository')
    if version and not TAG.fullmatch(version): raise ValueError('版本必须为 v1.2.3 或 v1.2.3-rc.1 格式')
    suffix = 'tags/' + version if version else 'latest'
    rel = fetch_json(f'https://api.github.com/repos/{repo}/releases/{suffix}', token)
    tag = rel.get('tag_name', '')
    if rel.get('draft') or not TAG.fullmatch(tag) or (version and tag != version) or (not version and rel.get('prerelease')): raise ValueError('发行版本不匹配')
    name = f'dao-{tag[1:]}-linux-{arch}.zip'
    def asset(name):
        rows = [a for a in rel.get('assets', []) if a.get('name') == name and a.get('state') == 'uploaded']
        if len(rows) != 1: raise ValueError('该版本缺少唯一的 ' + name)
        return rows[0]
    bundle, sums = asset(name), asset('SHA256SUMS')
    if not 0 < bundle['size'] <= 2*1024**3 or not 0 < sums['size'] <= 1024**2: raise ValueError('发行文件大小不合法')
    with urllib.request.build_opener(Redirect(CDN)).open(asset_url(repo,sums,token), timeout=45) as r:
        raw = r.read(1024**2+1)
        if len(raw) > 1024**2: raise ValueError('校验文件过大')
    hashes = [p[0] for line in raw.decode().splitlines() if len(p:=line.split()) == 2 and p[1].lstrip('*') == name]
    if len(hashes) != 1 or not re.fullmatch('[a-fA-F0-9]{64}', hashes[0]): raise ValueError('缺少唯一有效的 SHA256')
    return dict(repo=repo, tag=tag, name=name, size=bundle['size'], sha256=hashes[0].lower(), url=asset_url(repo,bundle,token))

def download_bundle(manifest, dest, github=True):
    url, expected = manifest['url'], manifest['sha256']
    if not valid_https(url, CDN if github else None) or not re.fullmatch('[a-fA-F0-9]{64}', expected): raise ValueError('安装包地址或 SHA256 无效')
    digest = hashlib.sha256(); size = 0
    try:
        with urllib.request.build_opener(Redirect(CDN if github else None)).open(url, timeout=60) as r, open(dest,'wb') as out:
            if not valid_https(r.url, CDN if github else None): raise ValueError('安装包下载发生不可信跳转')
            while block := r.read(1024**2):
                size += len(block)
                if size > 2*1024**3: raise ValueError('安装包超过 2 GiB')
                out.write(block); digest.update(block)
    except urllib.error.HTTPError as e:
        raise ValueError(f'安装包 HTTP {e.code}；重跑命令可刷新下载授权') from None
    except (urllib.error.URLError, TimeoutError):
        raise ValueError('安装包下载中断；重跑命令可继续安装') from None
    if digest.hexdigest() != expected.lower() or (manifest.get('size') is not None and size != manifest['size']): raise ValueError('安装包大小或 SHA256 不匹配，未执行安装')

def extract_bundle(archive, target):
    with zipfile.ZipFile(archive) as z:
        if sum(i.file_size for i in z.infolist()) > 4*1024**3: raise ValueError('解压体积超过 4 GiB')
        seen = set()
        for i in z.infolist():
            p = PurePosixPath(i.filename)
            if p.is_absolute() or '..' in p.parts or '\\' in i.filename or stat.S_ISLNK(i.external_attr >> 16) or i.filename in seen: raise ValueError('发行包路径不安全或重复')
            seen.add(i.filename)
        z.extractall(target)
    helpers = list(Path(target).glob('*/deploy/install.py'))
    if len(helpers) != 1: raise ValueError('发行包缺少唯一安装器')
    return helpers[0].parent.parent

def ensure_stopped(role):
    name = 'dao' if role == 'main' else 'dao-worker'
    if subprocess.run(['systemctl','is-active','--quiet',name],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL).returncode == 0:
        raise ValueError(f'{name} 正在运行。升级前请暂停/完成任务，停止接收新任务，并执行 systemctl stop {name}，再重跑安装命令；不会自动中断运行中的服务。')

def node_request(config, action, body=None):
    controller = config['controller'].rstrip('/')
    u = urllib.parse.urlsplit(controller)
    if not valid_https(controller) or u.path or u.query or u.fragment or not re.fullmatch('[a-f0-9]{24}',config['node_id']): raise ValueError('主站地址或节点 ID 不合法')
    return fetch_json(controller + '/api/worker-install/' + config['node_id'] + '/' + action, config['token'], body)

def node_config(args, arch):
    pending = PENDING
    if args.enroll_file: args.enroll = Path(args.enroll_file).read_text().strip()
    if args.enroll:
        if not args.controller or not args.node or not re.fullmatch('[a-f0-9]{64}',args.enroll): raise ValueError('需要 --controller、--node 和有效安装码')
        SECRETS.append(args.enroll)
        claim_hash = hashlib.sha256(args.enroll.encode()).hexdigest()
        state = json.loads(pending.read_text()) if pending.exists() else {}
        if state.get('enrollment_hash') != claim_hash:
            state = dict(enrollment_hash=claim_hash, controller=args.controller.rstrip('/'), node_id=args.node, token=secrets.token_hex(32))
            atomic_json(pending,state) # Durable before the first redemption request.
        elif state['controller'] != args.controller.rstrip('/') or state['node_id'] != args.node:
            raise ValueError('同一安装码的接入地址/节点不一致')
        SECRETS.append(state['token'])
        if state.get('config'):
            cfg = state['config']; return cfg, node_request(cfg,'download',dict(arch=arch))['release'], pending
        request_cfg = dict(controller=state['controller'],node_id=state['node_id'],token=args.enroll)
        result = node_request(request_cfg,'claim',dict(arch=arch,node_token=state['token']))
        cfg = result['config']
        if cfg['token'] != state['token'] or cfg['node_id'] != state['node_id'] or cfg['controller'] != state['controller']: raise ValueError('兑换的节点身份不匹配')
        state['config'] = cfg; atomic_json(pending,state)
        return cfg,result['release'],pending
    source = Path(args.config or '/etc/dao-worker/config.json')
    if not source.is_file(): raise ValueError('首次安装 Worker 请使用主站生成的命令，或 --config 文件')
    cfg=json.loads(source.read_text());SECRETS.append(cfg['token'])
    return cfg,node_request(cfg,'download',dict(arch=arch))['release'],None

def run_logged(command, message, env=None):
    # Stream output through a bounded, redacted local installation log.
    with subprocess.Popen(command,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,env=env) as process:
        for line in process.stdout: log(line.rstrip())
        code = process.wait()
    if code: raise ValueError(message)

def prepare_hostname(etc=Path('/etc')):
    name = socket.gethostname()
    try:
        socket.getaddrinfo(name, None)
        return True
    except (OSError, UnicodeError):
        pass
    canonical = name.removesuffix('.').lower()
    labels = canonical.split('.')
    if len(canonical) > 253 or not all(re.fullmatch(r'[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?', label) for label in labels):
        log('主机名为特殊格式且无法解析，保留现有配置；请核对 /etc/hostname、/etc/hosts 和 NSS。')
        return False
    advice = f'主机名 {name} 无法解析；请核对 /etc/hostname、/etc/hosts 和 NSS，缺少本机映射时可补充 127.0.1.1 {name}。此问题不要求购买域名。'
    hosts = etc/'hosts'
    temporary = None
    try:
        if (etc/'hostname').read_text().strip().removesuffix('.').lower() != canonical:
            log(advice + ' 静态与运行中主机名不一致，未自动修改。'); return
        metadata = hosts.lstat()
        if not stat.S_ISREG(metadata.st_mode):
            log(advice + ' hosts 为特殊文件或符号链接，未自动修改。'); return
        original = hosts.read_bytes()
        rows = [line.split('#', 1)[0].split() for line in original.decode().splitlines()]
        existing = {alias.removesuffix('.').lower() for row in rows for alias in row[1:]}
        if canonical in existing:
            log(advice + ' 已有名称映射，保留原配置，请检查解析服务。'); return
        # Add the conventional short alias only when no existing entry owns it.
        aliases = [canonical]
        # NSS files does not strip a DNS root dot like a DNS resolver would.
        if name.endswith('.'):
            aliases.append(canonical + '.')
        if len(labels) > 1 and labels[0] not in existing:
            aliases.append(labels[0])
        nss = (etc/'nsswitch.conf').read_text()
        host_rules = [line.split('#', 1)[0].split(':', 1)[1].split() for line in nss.splitlines() if line.lstrip().startswith('hosts:')]
        if not host_rules or 'files' not in host_rules[0]:
            log(advice + ' NSS 未启用 files，未自动修改。'); return
        backup = hosts.with_name('hosts.dao-backup-' + secrets.token_hex(6))
        fd = os.open(backup, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(fd, 'wb') as out:
            out.write(original); out.flush(); os.fsync(out.fileno())
        fd, temporary = tempfile.mkstemp(prefix='.dao-hosts-', dir=etc)
        with os.fdopen(fd, 'wb') as out:
            out.write(original + (b'' if original.endswith(b'\n') else b'\n') + ('127.0.1.1\t' + ' '.join(aliases) + ' # DAO local hostname\n').encode())
            out.flush(); os.fsync(out.fileno())
            os.fchown(out.fileno(), metadata.st_uid, metadata.st_gid)
            os.fchmod(out.fileno(), stat.S_IMODE(metadata.st_mode))
        if hosts.is_symlink() or hosts.read_bytes() != original:
            log(advice + ' hosts 安装期间发生变化，未替换。'); return
        os.replace(temporary, hosts)
        log(f'已补齐本机主机名映射 {name}；原 hosts 保留在 {backup}。')
        try:
            socket.getaddrinfo(name, None)
            return True
        except (OSError, UnicodeError):
            log(advice + ' 映射已写入，但解析仍异常，请检查 NSS 配置。')
    except (OSError, UnicodeError) as error:
        log(advice + f' 自动处理未完成（{type(error).__name__}），请由服务器管理员检查。')
    finally:
        if temporary and os.path.exists(temporary): os.unlink(temporary)

def extra_option(extra, flag):
    for index, value in enumerate(extra):
        if value == flag:
            if index + 1 >= len(extra): raise ValueError(flag + ' 缺少值')
            return extra[index + 1]
        if value.startswith(flag + '='): return value.split('=', 1)[1]
    return None

def prepare_postgres(args, extra, etc=Path('/etc')):
    # Public bootstrap also fixes old rc.3 bundles, including Workers paired with
    # an already running rc.3 controller. Application binaries stay unchanged.
    if shutil.which('pg_lsclusters'): return
    if args.role == 'main':
        if (etc/'dao/config.json').exists() or extra_option(extra, '--database-config') is not None: return
    else:
        source = extra_option(extra, '--config')
        for path in ([Path(source)] if source else []) + [etc/'dao-worker/config.json']:
            if path.is_file():
                value = json.loads(path.read_text())
                if not isinstance(value, dict): raise ValueError('Worker 配置必须是 JSON 对象')
                if value.get('database_dsn'): return
    log('准备 PostgreSQL 管理依赖，兼容首次安装的预配置流程。')
    env = dict(os.environ, DEBIAN_FRONTEND='noninteractive', NEEDRESTART_MODE='a')
    message = 'PostgreSQL 管理依赖安装失败，未启动 DAO 安装器；请检查 apt 日志后重试。'
    run_logged(['apt-get', 'update'], message, env)
    run_logged(['apt-get', 'install', '-y', '--no-install-recommends', 'postgresql-common'], message, env)

def run_helper(args, root, extra):
    if not Path('/run/systemd/system').is_dir():
        raise ValueError('安装需要正在运行的 systemd，尚未修改主机名或安装数据库依赖')
    prepare_hostname()
    prepare_postgres(args, extra)
    command = [sys.executable,str(root/'deploy/install.py'),args.role,*extra]
    run_logged(command, '安装未完成；查看上方失败步骤和本机安装日志')

def main(argv=None):
    parser = argparse.ArgumentParser(description='DAO GitHub 一键安装；默认安装正式版，预览版用 --version。')
    parser.add_argument('role',choices=['main','worker']);parser.add_argument('local')
    parser.add_argument('--repair-hostname', action='store_true', help='仅修复缺失的本机主机名映射，不下载或重启 DAO')
    for flag in ['repo','version','github-token-file','bundle-dir','bundle-url','sha256','controller','node','enroll','enroll-file','config']:
        parser.add_argument('--'+flag)
    args, extra = parser.parse_known_args(argv)
    if args.role == 'main' and any([args.controller,args.node,args.enroll,args.enroll_file,args.config]): raise ValueError('节点参数仅适用于 Worker')
    if args.enroll and args.enroll_file: raise ValueError('安装码只能提供一次')
    if bool(args.bundle_url) != bool(args.sha256): raise ValueError('--bundle-url 必须同时提供 --sha256')
    if args.bundle_url and args.bundle_dir: raise ValueError('--bundle-url 与 --bundle-dir 不能同时使用')
    if os.geteuid()!=0: raise ValueError('请以 root 或 sudo bash 运行')
    arch = {'x86_64':'amd64','aarch64':'arm64'}.get(platform.machine())
    if not arch: raise ValueError('仅支持 Linux amd64/arm64')
    if args.repair_hostname:
        if extra or any(getattr(args, key.replace('-', '_')) is not None for key in ['repo','version','github-token-file','bundle-dir','bundle-url','sha256','controller','node','enroll','enroll-file','config']):
            raise ValueError('--repair-hostname 必须单独使用，不接受安装或下载参数')
        if not prepare_hostname(): raise ValueError('主机名解析尚未修复，请按上方提示检查服务器配置；DAO 服务未操作')
        log('主机名解析检查通过；DAO 服务未操作。')
        return 0
    ensure_stopped(args.role)
    global LOG
    directory=Path(os.environ.get('DAO_INSTALL_LOG_DIR','/var/log/dao-install'));directory.mkdir(parents=True,exist_ok=True,mode=0o700)
    path=directory/(args.role+'-'+datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d-%H%M%S')+'-'+secrets.token_hex(3)+'.log')
    fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600);LOG=os.fdopen(fd,'w')
    for old in sorted(directory.glob(args.role+'-*.log'))[:-10]: old.unlink()
    log('DAO '+args.role+' 安装开始；架构 '+arch+'；日志 '+str(path))
    pending=None;cfg=None;manifest=None
    with tempfile.TemporaryDirectory(prefix='dao-install-') as tmp:
        tmp=Path(tmp);root=Path(args.bundle_dir or args.local)
        local=(root/'deploy/install.py').is_file() and not args.version and not args.repo
        if args.enroll or args.enroll_file or (args.role=='worker' and not args.bundle_url and not args.bundle_dir and not local):
            cfg,manifest,pending=node_config(args,arch)
            if args.version and args.version!=manifest['tag']:raise ValueError('Worker 必须安装主站指定版本')
        elif args.bundle_url:
            manifest=dict(url=args.bundle_url,sha256=args.sha256)
        elif not local:
            repo=(args.repo or REPO).strip()
            if args.role=='worker':cfg,manifest,pending=node_config(args,arch)
            else:
                if not repo:
                    raise ValueError('请通过 --repo owner/repo 或环境变量 DAO_RELEASE_REPO 指定 GitHub 发行仓库')
                token=Path(args.github_token_file).read_text().strip() if args.github_token_file else os.environ.get('DAO_RELEASE_TOKEN','')
                if not token:
                    # Reading the terminal still works when the script was fetched with curl.
                    token=getpass.getpass('GitHub 发行仓库只读 Token（不回显；仅主站保存用于节点下载）：').strip()
                SECRETS.append(token)
                manifest=github_manifest(repo,args.version,arch,token)
                source=tmp/'release-source.json';atomic_json(source,dict(repo=repo,token=token));extra+=['--release-source',str(source)]
        if manifest:
            log('下载安装包：'+manifest.get('name','指定 HTTPS 包')+'；版本 '+manifest.get('tag','手动指定'))
            archive=tmp/'release.zip';download_bundle(manifest,archive,github=not bool(args.bundle_url));log('安装包 SHA256 校验通过')
            root=extract_bundle(archive,tmp/'bundle')
        if not (root/'deploy/install.py').is_file(): raise ValueError('缺少安装器')
        if cfg:
            config=tmp/'worker.json';atomic_json(config,cfg);extra+=['--config',str(config)]
        elif args.config:extra+=['--config',args.config]
        run_helper(args,root,extra)
        if cfg:
            log('等待主站确认节点版本与配置同步')
            deadline=time.monotonic()+90
            while time.monotonic()<deadline:
                if node_request(cfg,'status').get('ready'):break
                time.sleep(3)
            else:raise ValueError('服务已启动，但主站尚未确认就绪；请检查节点日志，未报告安装成功')
            if pending:pending.unlink(missing_ok=True)
        log('DAO 安装完成'+('；版本 '+manifest['tag'] if manifest and manifest.get('tag') else ''))
    return 0

if __name__ == '__main__':
    try: sys.exit(main())
    except (OSError,ValueError,KeyError,EOFError,zipfile.BadZipFile) as error:
        # Never include urllib exceptions (signed URLs) in install logs.
        log('DAO 安装失败：'+(str(error) if isinstance(error,ValueError) else type(error).__name__+'；检查网络、权限和安装日志'))
        sys.exit(1)

